'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  bolt:'M13 2 4 14h7l-1 8 10-13h-7z', dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z', camera:'M3 6h12v12H3z M15 10l6-3v10l-6-3', bulb:'M9 18h6 M10 21h4 M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2', workflow:'M5 3h5v5H5z M14 16h5v5h-5z M7.5 8v10H14 M10 5.5h6.5V16', zones:'M3 3h5v5H3z M16 3h5v5h-5z M3 16h5v5H3z M16 16h5v5h-5z M8 5.5h8 M5.5 8v8 M18.5 8v8 M8 18.5h8', devices:'M4 4h16v16H4z M8 8v2 M12 8v2 M16 8v2 M8 14v2 M12 14v2 M16 14v2', pulse:'M2 12h5l3-8 4 16 3-8h5', history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 3 2 2-1 3 3 2 1 3h4l2-2 3-1 1-3 3-2-1-4-3-1-1-3z', cloud:'M7 18a5 5 0 0 1-1-10 7 7 0 0 1 13 2 4 4 0 0 1-1 8z', building:'M4 21V3h12v18 M16 9h4v12 M8 7h1 M12 7h1 M8 11h1 M12 11h1 M8 15h1 M12 15h1 M2 21h20', chevron:'M9 5l7 7-7 7', plus:'M12 5v14 M5 12h14', expand:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5', person:'M12 3a3 3 0 1 1 0 6 3 3 0 0 1 0-6 M6 21v-4a6 6 0 0 1 12 0v4', logout:'M9 4H4v16h5 M9 12h12 M16 7l5 5-5 5', arrow:'M5 12h14 M14 7l5 5-5 5', check:'M5 12l4 4L19 6', close:'M6 6l12 12 M18 6 6 18', edit:'m15 3 6 6-12 12H3v-6z M12 6l6 6', trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7', play:'m8 4 12 8-12 8z', info:'M12 8v1 M12 12v5 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20', download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4', upload:'M12 16V3 M7 8l5-5 5 5 M4 17v4h16v-4', link:'m9 15 6-6 M7 14l-2 2a4 4 0 0 0 5 5l4-4 M10 7l4-4a4 4 0 0 1 7 5l-4 4', shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6', code:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18', search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6', bell:'M4 17h16l-2-4V9a6 6 0 0 0-12 0v4z M10 21h4', circle:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20', back:'M20 12H4 M10 6l-6 6 6 6', save:'M4 3h14l3 3v15H3V3z M7 3v6h10V3 M7 21v-8h10v8'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.circle}"/></svg>`;
const badge = (text, kind='') => `<span class="badge ${kind}">${esc(text)}</span>`;
let state, me, mode='edge', page='overview', area='All areas', query='', ws, toastTimer, refreshTimer, currentAuto=null, cloudSite=null, cloudOnline=false, sites=[], zoneCamera=null, zoneDraft=[], zoneType='zones', zoneLocal=null;
let editorDirty=false;
let activePeer=null;
const pages = {overview:['Overview','Your factory, in focus.'],cameras:['Live cameras','A clear view of every space.'],switches:['Switch controls','Every circuit. One place.'],automations:['Automations','Make your space respond.'],zones:['Zones & masks','Intelligence starts with boundaries.'],devices:['Devices','Your connected infrastructure.'],health:['System health','A closer look at your controller.'],history:['Activity & history','Every change, accounted for.'],settings:['Settings','Built around your installation.'],sites:['Cloud sites','Every installation, connected.']};
async function api(url, body, method) {
  const options={method:method || (body === undefined ? 'GET':'POST'),headers:{'X-LumiNext':'1'}};
  if(body !== undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body);}
  const response=await fetch(url,options);
  if(response.status===401 && !url.includes('/auth/')) {await boot();throw Error('Session expired. Please sign in.');}
  const data=await response.json().catch(()=>({detail:'Unexpected server response'}));
  if(!response.ok) throw Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));
  return data;
}
function toast(text, failure=false){const t=$('#toast');t.textContent=text;t.className='visible'+(failure?' failure':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',6000);}
async function guarded(fn){try{return await fn();}catch(e){toast(e.message,true);}}
function date(value, options={}){return value?new Date(value*1000).toLocaleString('en-GB',{timeZone:state?.settings?.timezone||'Asia/Dhaka',...options}):'—';}
function timeAgo(value){if(!value)return 'Never';const seconds=Math.max(0,Math.floor(Date.now()/1000-value));return seconds<60?`${seconds}s ago`:seconds<3600?`${Math.floor(seconds/60)}m ago`:seconds<86400?`${Math.floor(seconds/3600)}h ago`:`${Math.floor(seconds/86400)}d ago`;}
function isAdmin(){return me?.role==='admin';}
function isRemote(){return mode==='cloud' && cloudSite;}
function localAdmin(){return isAdmin()&&!isRemote();}
const cameras=()=>state?.cameras||[];
const devices=()=>state?.devices||[];
const entities=()=>state?.entities||[];
const switches=()=>entities().filter(e=>e.type==='switch');
const occupancy=c=>entities().find(e=>e.id===`occupancy.${c.id}`);
function matching(list){return list.filter(x=>(area==='All areas'||x.area===area)&&(!query||`${x.name} ${x.area} ${x.id}`.toLowerCase().includes(query.toLowerCase())));}
function setPage(value){if(editorDirty&&page==='automations'&&value!==page){confirmDialog('Leave the automation editor?','Your unsaved YAML will be discarded.',()=>{editorDirty=false;setPage(value);});return;}page=value;query='';area='All areas';location.hash=value;render();}
function goButton(label, target, cls='ghost'){return `<button class="${cls}" data-page="${target}">${esc(label)}${icon('arrow')}</button>`;}
function modal(title, body, after){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button data-close aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;const d=$('#dialog');if(!d.open)d.showModal();$('[data-close]',d).onclick=()=>d.close();if(after)after(d);}
function confirmDialog(title,text,fn){modal(title,`<p class="form-note">${esc(text)}</p><div class="dialog-actions"><button data-cancel>Cancel</button><button class="primary" data-confirm>Continue</button></div>`,d=>{$('[data-cancel]',d).onclick=()=>d.close();$('[data-confirm]',d).onclick=()=>guarded(async()=>{d.close();await fn();});});}
async function boot(){clearTimeout(refreshTimer);refreshTimer=null;if(ws){ws.onclose=null;ws.close();}me=null;try{const status=await api('/api/auth/status');mode=status.mode;if(status.setup_required){renderAuth(true);return;}try{me=await api('/api/auth/me');}catch{renderAuth(false);return;}if(mode==='cloud'){sites=await api('/api/cloud/sites');page='sites';}else{state=await api('/api/state');const hash=location.hash.slice(1);page=pages[hash]?hash:'overview';}render();connect();}catch(e){$('#app').innerHTML=`<div class="loading">Controller unavailable<span>${esc(e.message)}</span><button id="retry">Reconnect</button></div>`;$('#retry').onclick=boot;}}
function renderAuth(setup){$('#app').innerHTML=`<main class="login-screen"><section class="login-art"><div class="brand"><div class="brand-mark">${icon('bolt')}</div><span>Lumi<em>Next</em></span></div><div><div class="eyebrow">INTELLIGENCE, ON YOUR TERMS</div><h1>A space that<br>knows when<br>to <em>light up.</em></h1><p>Local vision. Thoughtful automation. Complete control.<br>Your entire facility, working together.</p></div><footer>FACTORY NEXT LIMITED <span class="muted">&nbsp; / &nbsp; LUMINEXT PLATFORM</span></footer></section><section class="login-form"><div class="eyebrow">${mode==='cloud'?'CLOUD MANAGEMENT':'LOCAL CONTROLLER'}</div><h2>${setup?'Welcome to LumiNext':'Welcome back'}</h2><p class="subtitle">${setup?'Create your administrator account to set up this installation.':'Sign in to your '+(mode==='cloud'?'cloud console.':'local workspace.')}</p><form id="auth-form" class="form-stack"><label>Username<input name="username" autocomplete="username" required minlength="3" maxlength="64" placeholder="Your username"></label><label>Password<input name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" required minlength="12" maxlength="256" placeholder="${setup?'At least 12 characters':'Your password'}"></label><div class="error" id="auth-error" role="alert"></div><button class="primary" type="submit">${setup?'Create administrator account':'Sign in'}${icon('arrow')}</button></form><div class="login-footer">${icon('shield')} ${setup?'No default credentials. Your account, your installation.':'Secure access · Video stays on your local network'}</div>${setup?'<p class="auth-note">Complete first-run setup on a trusted network before exposing this service. Cloud installations need HTTPS and secure cookies.</p>':''}</section></main>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const button=$('button',form);button.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(setup)await api('/api/auth/setup',data);await api('/api/auth/login',data);await boot();}catch(err){$('#auth-error').textContent=err.message;button.disabled=false;}};}
function connect(){if(ws){ws.onclose=null;ws.close();}ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/api/ws`);ws.onopen=()=>{$('.connection')?.classList.remove('offline');};ws.onmessage=e=>{const msg=JSON.parse(e.data);if(msg.type==='ping')return;if(msg.type==='entity'&&!isRemote()&&state){const index=state.entities.findIndex(x=>x.id===msg.entity.id);if(index>=0)state.entities[index]=msg.entity;else state.entities.push(msg.entity);}scheduleRefresh();};ws.onclose=()=>{const c=$('.connection');if(c)c.innerHTML='<span class="dot warn"></span>Reconnecting';setTimeout(async()=>{if(me){try{await api("/api/auth/me");connect();}catch{await boot();}}},3000);};}
function scheduleRefresh(){if(refreshTimer)return;refreshTimer=setTimeout(()=>{refreshTimer=null;refresh();},500);}
async function refresh(){try{if(mode==='cloud'){sites=await api('/api/cloud/sites');if(cloudSite){const result=await api(`/api/cloud/sites/${cloudSite}/state`);state=result.snapshot;cloudOnline=result.online;window.cloudCommands=result.commands;}}else state=await api('/api/state');if(!$('#dialog').open&&!editorDirty&&page!=='zones'&&!(page==='automations'&&$('#yaml-editor')===document.activeElement)){const search=$('#search');const activeSearch=document.activeElement===search;const pos=search?.selectionStart;render();if(activeSearch){$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);}}else updateConnection();}catch(e){console.warn('State refresh failed');}}
function updateConnection(){const c=$('.connection');if(c)c.innerHTML=`<span class="dot ${isRemote()&&!cloudOnline?'off':''}"></span>${isRemote()?(cloudOnline?'Site connected':'Site offline'):'Controller connected'}`;}
function render(){const names=pages[page]||pages.overview;const nav=[['overview','dashboard','Overview'],['cameras','camera','Live cameras'],['switches','bulb','Switch controls'],['automations','workflow','Automations'],['zones','zones','Zones & masks']];const manage=[['devices','devices','Devices'],['health','pulse','System health'],['history','history','Activity & history'],['settings','settings','Settings']];const navHTML=items=>items.map(([id,ic,label])=>`<button data-page="${id}" aria-label="${label}" title="${label}" class="${page===id?'active':''}">${icon(ic)}<span>${label}</span>${id==='cameras'&&cameras().length?`<span class="count">${cameras().length}</span>`:''}</button>`).join('');$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('bolt')}</div><span>Lumi<em>Next</em></span></div><div class="site-tag">${icon('building')}<div><strong>${esc(isRemote()?sites.find(s=>s.id===cloudSite)?.name:state?.settings?.name||'Cloud console')}</strong><small>${mode==='cloud'?'Cloud management':'Local installation · Edge controller'}</small></div></div>${mode==='cloud'?`<div class="nav-label">Portfolio</div><nav class="nav">${navHTML([['sites','cloud','All installations']])}</nav>`:''}${mode!=='cloud'||cloudSite?`<div class="nav-label">Workspace</div><nav class="nav">${navHTML(nav)}</nav><div class="nav-label" style="margin-top:27px">Manage</div><nav class="nav">${navHTML(manage)}</nav>`:''}<div class="sidebar-bottom"><div class="local-status"><span class="dot"></span>${mode==='cloud'?'Cloud console':'Local processing enabled'}</div><div class="user"><div class="avatar">${esc(me.username.slice(0,2).toUpperCase())}</div><div><strong>${esc(me.username)}</strong><small>${isAdmin()?'Administrator':'Operator'}</small></div><button class="logout" id="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">Workspace ${icon('chevron')} <strong>${names[0]}</strong></div><div class="topbar-right">${isRemote()?`<select class="select-site" id="site-select" aria-label="Installation">${sites.map(s=>`<option value="${esc(s.id)}" ${s.id===cloudSite?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:''}<span class="clock">${date(Date.now()/1000,{day:'2-digit',month:'short',year:'numeric'})}</span><span class="connection"><span class="dot"></span>Controller connected</span></div></header><div class="content" id="content">${renderPage()}<div class="footer-note"><span>LumiNext <span class="muted">/</span> ${mode==='cloud'?'Cloud management':'Local intelligence, connected spaces'}</span><span>v0.1.1 &nbsp; · &nbsp; Factory Next Limited</span></div></div></main></div>`;bind();updateConnection();}
function pageHead(extra=''){return `<div class="page-head"><div><div class="eyebrow">${page==='overview'?'WORKSPACE OVERVIEW':mode==='cloud'?'CLOUD MANAGEMENT':'LUMINEXT WORKSPACE'}</div><h1>${pages[page][1]}</h1><p class="subtitle">${({overview:'Your cameras, occupancy and lighting — connected in real time.',cameras:'Live visibility across your facility. Video is never recorded.',switches:'Control relays manually. Overrides hold until mapped spaces are clear.',automations:'Write familiar YAML or start with the visual builder.',zones:'Draw detection zones and exclusion masks using relative coordinates.',devices:'Connect IP cameras and ESPHome wall switches to your local controller.',health:'Live controller metrics and per-camera detection telemetry.',history:'State changes, manual controls, automation traces and configuration events.',settings:'Manage your site, access, backups and cloud connection.',sites:'A secure connection to each local controller. Local operation comes first.'})[page]}</p></div><div class="actions">${extra}</div></div>`;}
function simulationBanner(){if(!cameras().some(c=>c.simulated)&&!devices().some(d=>d.simulated))return '';return `<div class="banner">${icon('info')}<span><strong>Simulation workspace.</strong> Simulated cameras and relays are labeled throughout. Occupancy changes are test inputs; no physical device is connected through these entries.</span><a href="#devices" data-page="devices">Connect your devices ${icon('arrow')}</a></div>`;}
function filterRow(showSearch=true){const areas=[...new Set([...cameras(),...devices()].map(c=>c.area))];return `<div class="filter-row">${showSearch?`<input class="search" id="search" type="search" aria-label="Search" placeholder="Search ${page==='switches'?'wall switches':'devices'}…" value="${esc(query)}">`:''}<select id="area-filter" aria-label="Filter by area"><option>All areas</option>${areas.map(a=>`<option ${a===area?'selected':''}>${esc(a)}</option>`).join('')}</select><small>${area==='All areas'?'Entire installation':esc(area)}</small></div>`;}
function renderPage(){if(page==='sites')return renderSites();if(mode==='cloud'&&!state)return `${pageHead()}<div class="empty">${icon('cloud')}<h2>Waiting for the local controller</h2><p>Enroll this site and connect its local controller to begin receiving configuration and status.</p></div>`;const stale=isRemote()&&!cloudOnline?'<div class="banner">Site offline. Values below are the last synchronized observations. Remote controls are disabled until the local controller reconnects.</div>':'';return stale+(({overview:renderOverview,cameras:renderCameras,switches:renderSwitches,automations:renderAutomations,zones:renderZones,devices:renderDevices,health:renderHealth,history:renderHistory,settings:renderSettings})[page]?.()||'');}
function stats(){const cams=cameras(),online=cams.filter(c=>occupancy(c)?.available).length,occupied=cams.filter(c=>occupancy(c)?.state===true).length,relays=switches(),on=relays.filter(s=>s.state===true).length;return `<div class="stats"><div class="stat"><div class="stat-top">${icon('camera')}Connected cameras</div><div class="stat-number">${online}<small>/ ${cams.length}</small></div><div class="stat-foot"><span class="dot ${online?'':'off'}"></span>${cams.some(c=>c.simulated)?'Includes simulated cameras':online===cams.length?'All configured streams online':`${cams.length-online} awaiting a connection`}</div></div><div class="stat accent"><div class="stat-top">${icon('person')}Occupied spaces</div><div class="stat-number">${occupied}<small>of ${cams.length} views</small></div><div class="stat-foot"><span class="dot"></span>Person occupancy · current state</div></div><div class="stat"><div class="stat-top">${icon('bulb')}Lights switched on</div><div class="stat-number">${on}<small>/ ${relays.length} relays</small></div><div class="stat-foot">${relays.filter(s=>s.override).length} manual overrides active</div></div><div class="stat"><div class="stat-top">${icon('workflow')}Active automations</div><div class="stat-number">${(state?.automations||[]).filter(a=>a.enabled).length}<small>rules</small></div><div class="stat-foot">${state?.automations?.length?'Rules apply locally':'Ready for your first YAML automation'}</div></div></div>`;}
function emptyInstall(){return `<div class="empty">${icon('building')}<h2>Your workspace is ready.</h2><p>Start with a camera or an ESPHome wall switch. You can also explore a labeled simulation with 12 cameras, 36 wall switches and 144 relays.</p>${localAdmin()?'<button class="primary" id="load-demo">Explore simulation</button> <button data-add-device>Connect a device</button>':'<p>An administrator can configure devices for this installation.</p>'}</div>`;}
function renderOverview(){const extra=localAdmin()?'<button data-add-camera>'+icon('plus')+'Add camera</button>':'';return pageHead(extra)+simulationBanner()+stats()+(cameras().length?`<div class="section-line"><h2>Camera overview <small>${cameras().length} CAMERAS</small></h2><div class="segmented">${['All areas',...new Set(cameras().map(c=>c.area))].map(a=>`<button data-area="${esc(a)}" class="${a===area?'active':''}">${a==='All areas'?'All cameras':esc(a)}</button>`).join('')}</div></div><div class="camera-grid">${matching(cameras()).slice(0,6).map(cameraCard).join('')}</div><div class="section-line" style="margin-top:16px"><small>Showing ${Math.min(matching(cameras()).length,6)} of ${cameras().length} cameras</small>${goButton('View all cameras','cameras')}</div><div class="below-grid"><section class="panel"><div class="panel-head"><h2>Lighting controls</h2><button class="text-btn" data-page="switches">View all ${icon('arrow')}</button></div><div class="panel-body">${switches().slice(0,4).map(relayRow).join('')||'<p class="help">Connect an ESPHome device to see relays.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Recent activity</h2><button class="text-btn" data-page="history">View history ${icon('arrow')}</button></div><div class="panel-body">${(state.events||[]).slice(0,4).map(eventRow).join('')||'<p class="help">Changes will appear here.</p>'}</div></section></div>`:emptyInstall());}
function scene(camera){const index=cameras().indexOf(camera),occupied=occupancy(camera)?.state===true;const variant=Math.max(0,index)%4;return `<svg class="scene" viewBox="0 0 640 360" preserveAspectRatio="xMidYMid slice" aria-label="Illustrated simulation — not a camera feed"><defs><linearGradient id="floor${index}" x2="0" y2="1"><stop stop-color="#4a5654"/><stop offset="1" stop-color="#273b40"/></linearGradient><linearGradient id="wall${index}" x2="0" y2="1"><stop stop-color="#465959"/><stop offset="1" stop-color="#293a40"/></linearGradient><radialGradient id="shade${index}"><stop stop-color="#06141a" stop-opacity="0"/><stop offset="1" stop-color="#041118" stop-opacity=".55"/></radialGradient></defs><rect width="640" height="360" fill="#34474a"/><path d="M0 0h640v142L320 108 0 142z" fill="#283b40"/><path d="M0 135 320 95l320 40v225H0z" fill="url(#floor${index})"/><path d="M0 0h640v133L320 90 0 133z" fill="url(#wall${index})"/><path d="M70 0v100 M198 0v90 M448 0v90 M568 0v110 M0 44h640 M0 85h640" stroke="#72908e" stroke-width="5" opacity=".4"/><path d="m80 360 160-252 M210 360l70-252 M430 360l-70-252 M560 360 400 108 M0 175h640 M0 241h640 M0 320h640" stroke="#9aaca0" opacity=".16"/><path d="M74 50h140 M277 31h100 M429 50h140" stroke="#e5edcf" stroke-width="7" opacity=".65"/>${variant!==3?Array.from({length:3},(_,i)=>`<g transform="translate(${45+i*200},${145+(i%2)*15})"><path d="m0 0 115-14 34 50-128 18z" fill="${variant===1?'#5f736c':'#69766b'}"/><path d="m21 54 128-18v17L21 72z" fill="#344b4c"/><path d="M28 62v42 M137 49v38" stroke="#283a3d" stroke-width="7"/><path d="m20 6 32-4 10 13-34 5z M76-2l27-3 13 13-30 5z" fill="#b2b6a0" opacity=".55"/></g>`).join(''):`<path d="M15 160v140h150V148z M475 145v155h150V160z" fill="#647266"/><path d="M26 170v120 M80 165v130 M140 160v130 M490 155v140 M550 163v132 M610 170v120" stroke="#2f4649" stroke-width="5"/>`}<path d="M20 360 235 125 M620 360 405 125" stroke="#c9b76a" stroke-width="3" opacity=".45"/>${occupied?`<g transform="translate(338 173)"><ellipse cy="69" rx="22" ry="7" fill="#071b20" opacity=".6"/><circle cy="-3" r="10" fill="#a2ac9d"/><path d="m-11 11-5 31 11 5-4 25h10l7-27 10 26h10L14 39 9 10z" fill="#7d9991"/><rect x="-31" y="-23" width="65" height="104" rx="2" stroke="#b8f36c" fill="#b8f36c0c" stroke-width="2"/><rect x="-31" y="-40" width="65" height="17" fill="#b8f36c"/><text x="-25" y="-28" fill="#142413" font-size="10" font-family="monospace">person · sim</text></g>`:''}<rect width="640" height="360" fill="url(#shade${index})"/><text x="320" y="330" text-anchor="middle" fill="#abc1ba" opacity=".35" font-size="10" letter-spacing="3" font-family="monospace">SIMULATED ENVIRONMENT</text></svg>`;}
function cameraCard(c){const e=occupancy(c),available=e?.available,occupied=e?.state===true,unknown=e?.state==='unknown'||!available;return `<article class="camera-card"><div class="camera-visual" data-camera="${esc(c.id)}" role="button" tabindex="0" aria-label="Open ${esc(c.name)}">${c.simulated?scene(c):available&&!isRemote()?`<img src="/api/cameras/${encodeURIComponent(c.id)}/live" alt="${esc(c.name)} live feed" loading="lazy">`:`<div style="height:100%;display:grid;place-items:center;color:#607d85">${icon('camera')}<span class="help">${isRemote()?'Video stays at the local site':c.has_stream?'Waiting for detection worker':'Stream not configured'}</span></div>`}<div class="camera-top"><span class="video-label ${c.simulated?'sim':available?'live':''}"><span class="dot ${c.simulated?'warn':available?'':'off'}"></span>${c.simulated?'SIMULATION':available?'LIVE':'OFFLINE'}</span><span class="video-label mono">${esc(c.id.toUpperCase().replace('CAM_','CAM '))}</span></div><span class="cam-time">${esc(c.area.toUpperCase())} &nbsp; / &nbsp; ${c.simulated?'TEST VIEW':'LOCAL FEED'}</span><span class="cam-expand">${icon('expand')}</span></div><div class="camera-info"><div class="camera-title"><h3>${esc(c.name)}</h3>${badge(unknown?'Unknown':occupied?'Occupied':'Clear',unknown?'neutral':occupied?'':'neutral')}</div><div class="camera-meta"><span class="area">${esc(c.area)}</span><span>${c.zones?.length||0} zone${c.zones?.length===1?'':'s'}</span><span>${c.simulated?'Test input':c.metrics?.fps?c.metrics.fps+' fps':'— fps'}</span></div></div></article>`;}
function renderCameras(){return pageHead(localAdmin()?'<button class="primary" data-add-camera>'+icon('plus')+'Add camera</button>':'')+simulationBanner()+filterRow()+`<div class="camera-grid">${matching(cameras()).map(cameraCard).join('')||emptyInstall()}</div>`;}
function relayRow(e){return `<div class="relay-mini"><div class="bulb ${e.state===true?'on':''}">${icon('bulb')}</div><div class="relay-text"><strong>${esc(e.name)}</strong><small>${esc(e.area)} · ${e.override?'Manual override':e.available?'Automation ready':'Offline'}${e.simulated?' · Simulated':''}</small></div>${e.override?badge('Manual','amber'):''}<button class="toggle ${e.state===true?'on':''}" data-relay="${esc(e.id)}" role="switch" aria-checked="${e.state===true}" aria-label="Toggle ${esc(e.name)}" ${!e.available||(isRemote()&&!cloudOnline)?'disabled':''}></button></div>`;}
function deviceCard(d,admin=false){const relays=switches().filter(e=>e.device_id===d.id);return `<section class="device-card"><div class="section-line"><h3>${esc(d.name)}</h3>${badge(d.simulated?'Simulation':relays.some(e=>e.available)?'Online':'Offline',d.simulated?'amber':relays.some(e=>e.available)?'':'neutral')}</div><small>${esc(d.area)} · ${d.simulated?'Virtual wall switch':esc(d.host)}</small>${relays.map(e=>`<div class="relay-mini"><div class="bulb ${e.state===true?'on':''}">${icon('bulb')}</div><div class="relay-text"><strong>${esc(e.name.split(' · ').slice(1).join(' · ')||e.name)}</strong><small>${e.override?'Override until room clears':e.occupancy_sources?.length?e.occupancy_sources.length+' occupancy source'+(e.occupancy_sources.length===1?'':'s'):'No occupancy mapping'}</small></div>${e.override?badge('Manual','amber'):''}${localAdmin()?`<button class="map-button" data-map="${esc(e.id)}" title="Map occupancy sources">${icon('link')}</button>`:''}<button class="toggle ${e.state===true?'on':''}" data-relay="${esc(e.id)}" role="switch" aria-checked="${e.state===true}" aria-label="Toggle ${esc(e.name)}" ${!e.available||(isRemote()&&!cloudOnline)?'disabled':''}></button></div>`).join('')||'<p class="help" style="margin-top:20px">Relays appear after ESPHome discovery. Factory reset is excluded.</p>'}<div class="device-card-footer"><code>${esc(d.id)}</code>${admin&&localAdmin()?`<button data-device-edit="${esc(d.id)}">${icon('edit')}Edit device</button>`:`<span>${relays.filter(e=>e.state===true).length} / ${relays.length} on</span>`}</div></section>`;}
function renderSwitches(){return pageHead(localAdmin()?'<button class="primary" data-add-device>'+icon('plus')+'Add wall switch</button>':'')+simulationBanner()+`<div class="notice" style="margin-bottom:22px">${icon('info')} Manual changes pause automation for that relay until every mapped camera view reports clear. Offline and unknown sources do not release an override. Map occupancy sources using the link icon beside each relay.</div>`+filterRow()+`<div class="device-grid">${matching(devices()).map(d=>deviceCard(d)).join('')||emptyInstall()}</div>`;}
function renderDevices(){return pageHead(localAdmin()?'<button data-add-camera>'+icon('camera')+'Add camera</button><button class="primary" data-add-device>'+icon('plus')+'Add wall switch</button>':'')+simulationBanner()+filterRow()+`<div class="section-line"><h2>Wall switches <small>${devices().length} DEVICES</small></h2><small>ESPHome native API · encrypted connection</small></div><div class="device-grid">${matching(devices()).map(d=>deviceCard(d,true)).join('')||emptyInstall()}</div><div class="section-line" style="margin-top:30px"><h2>IP cameras</h2><small>${cameras().length} configured</small></div><div class="panel table-wrap"><table><thead><tr><th>Camera</th><th>Area</th><th>Detection</th><th>Stream</th><th>Configuration</th></tr></thead><tbody>${matching(cameras()).map(c=>`<tr><td><strong>${esc(c.name)}</strong><br><small>${esc(c.id)}</small></td><td>${esc(c.area)}</td><td>${c.width} × ${c.height} · ${c.fps} fps</td><td>${badge(c.simulated?'Simulation':c.has_stream?'Configured':'Not configured',c.simulated?'amber':'neutral')}</td><td>${localAdmin()?`<button class="compact" data-camera-edit="${esc(c.id)}">${icon('edit')}Edit</button>`:'Admin access required'}</td></tr>`).join('')}</tbody></table></div>`;}
const ruleExample=()=>{const sensor=entities().find(e=>e.type==='occupancy_sensor'),relay=switches()[0];return `alias: Occupancy lighting\ndescription: Turn on the mapped light when a person enters\nmode: parallel\nmax: 10\ntrigger:\n  - platform: state\n    entity_id: ${sensor?.id||'occupancy.camera_id'}\n    to: "on"\ncondition: []\naction:\n  - service: switch.turn_on\n    target:\n      entity_id: ${relay?.id||'switch.device_relay'}\n`;};
function renderAutomations(){const records=state?.automations||[],record=records.find(a=>a.id===currentAuto);const traces=record?(state.events||[]).filter(e=>e.kind==='trace'&&e.entity===record.id):[];return pageHead(isAdmin()?'<button class="primary" id="new-auto">'+icon('plus')+'New automation</button>':'')+`<div class="split"><aside><div class="section-line"><h2>Rules <small>${records.length}</small></h2></div><div class="automation-list">${records.map(a=>`<button class="automation-item ${a.id===currentAuto?'active':''}" data-auto="${esc(a.id)}"><strong>${esc(a.name)}</strong>${badge(a.enabled?'Enabled':'Disabled',a.enabled?'':'neutral')}<small> &nbsp; ${esc(a.rule.mode)}</small></button>`).join('')||'<p class="help">No automations yet. Start with the visual builder or write your own YAML.</p>'}</div><div class="rule-guide"><details><summary>Supported YAML</summary><p style="margin-top:12px">Triggers: <code>state</code>, <code>numeric_state</code>, <code>time</code>, <code>manual</code>.</p><p>Conditions: <code>state</code>, <code>numeric_state</code>, <code>time</code>, <code>and</code>, <code>or</code>, <code>not</code>.</p><p>Actions: <code>switch.turn_on</code>, <code>switch.turn_off</code>, <code>switch.toggle</code>, <code>delay</code>, <code>choose</code>, <code>luminext.notify</code>.</p><p>Modes: single, restart, queued, parallel.</p><p>HA-style subset. Templates, blueprints, arbitrary services and scripts are not supported. Occupancy mappings control overrides; they do not create lighting rules.</p></details></div></aside><section><div class="panel"><div class="editor-toolbar"><h3>${record?esc(record.name):'New automation'}</h3><div class="segmented"><button class="active" id="code-mode">${icon('code')}YAML</button><button id="visual-mode" ${!isAdmin()?'disabled':''}>${icon('workflow')}Visual builder</button></div></div><textarea id="yaml-editor" class="editor" spellcheck="false" aria-label="Automation YAML" ${!isAdmin()?'readonly':''}>${esc(record?.yaml||ruleExample())}</textarea><div class="editor-footer"><span class="validation" id="validation">${isRemote()?'Validated and applied by the local controller':'Validate your YAML before saving.'}</span>${record&&!isRemote()&&isAdmin()?`<button data-run-auto="${esc(record.id)}">${icon('play')}Run</button><button id="toggle-auto">${record.enabled?'Disable':'Enable'}</button>`:''}${isAdmin()?`${!isRemote()?'<button id="validate-auto">Validate</button>':''}<button class="primary" id="save-auto">${icon('save')}${isRemote()?'Send to site':'Save automation'}</button>`:''}</div></div>${record&&isAdmin()&&!isRemote()?`<button class="ghost danger compact" id="delete-auto" style="margin-top:12px">${icon('trash')}Delete automation</button>`:''}<div class="panel" style="margin-top:20px"><div class="panel-head"><h2>Run traces</h2><small>Conditions · actions · results</small></div><div class="trace-list">${traces.map(e=>`<details class="trace-summary"><summary><span>${badge(e.body.result,e.body.result==='failed'?'red':'neutral')} &nbsp; ${date(e.time,{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</span>${icon('chevron')}</summary><pre class="trace">${esc(JSON.stringify(e.body,null,2))}</pre></details>`).join('')||'<p class="help">Run this automation to see the trigger, condition result and each action here.</p>'}</div></div></section></div>`;}
function visualBuilder(){if(editorDirty){confirmDialog('Replace editor content?','The visual builder generates a new YAML rule. Your current edits will be replaced when you generate it.',openVisualBuilder);}else openVisualBuilder();}
function openVisualBuilder(){const sensors=entities().filter(e=>e.type==='occupancy_sensor');modal('Build an occupancy automation',`<form id="visual-form" class="form-stack"><label>Automation name<input name="alias" required value="Occupancy lighting"></label><div class="field-grid"><label>When this entity changes<select name="sensor">${sensors.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></label><label>To this state<select name="state"><option value="on">Occupied / on</option><option value="off">Clear / off</option></select></label><label>Control this relay<select name="relay">${switches().map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('')}</select></label><label>Action<select name="action"><option value="turn_on">Turn on</option><option value="turn_off">Turn off</option></select></label><label>Run mode<select name="mode"><option>parallel</option><option>single</option><option>restart</option><option>queued</option></select></label></div><p class="form-note">A manual override is respected automatically. Add off-delay in the camera settings to avoid flicker.</p><div class="dialog-actions"><button class="primary" type="submit">Generate YAML</button></div></form>`,d=>{$('#visual-form',d).onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.sensor||!f.relay){toast('Add a camera and relay first',true);return;}$('#yaml-editor').value=`alias: ${JSON.stringify(f.alias)}\nmode: ${f.mode}\nmax: 10\ntrigger:\n  - platform: state\n    entity_id: ${f.sensor}\n    to: "${f.state}"\ncondition: []\naction:\n  - service: switch.${f.action}\n    target:\n      entity_id: ${f.relay}\n`;editorDirty=true;d.close();};});}
function renderHealth(){const h=state.health||{};return pageHead()+`<div class="metrics-grid"><section class="panel"><div class="panel-head"><h2>Controller resources</h2>${badge('Live measurements')}</div><div class="panel-body">${[['CPU utilisation',h.cpu_percent],['Memory utilisation',h.memory_percent]].map(([name,v])=>`<div class="meter-row"><div class="meter-label"><span>${name}</span><span>${v??'—'}%</span></div><div class="meter-track"><span style="width:${Math.max(0,Math.min(100,v||0))}%"></span></div></div>`).join('')}<div class="status-row"><span>Memory used</span><strong>${h.memory_used_gb??'—'} GB</strong></div><div class="status-row"><span>Controller uptime</span><strong>${Math.floor((h.uptime_seconds||0)/3600)}h ${Math.floor(((h.uptime_seconds||0)%3600)/60)}m</strong></div><div class="status-row"><span>Inference device</span><strong>${esc(h.inference_device||'Not connected')}</strong></div><p class="help" style="margin-top:15px">These are measurements from the current host. N95 performance must be measured on the target machine with all camera streams connected.</p></div></section><section class="panel"><div class="panel-head"><h2>Service status</h2>${icon('pulse')}</div><div class="panel-body"><div class="status-row"><span>API & entity registry</span>${badge('Running')}</div><div class="status-row"><span>Realtime connection</span>${badge(ws?.readyState===1?'Connected':'Reconnecting',ws?.readyState===1?'':'amber')}</div><div class="status-row"><span>Detection worker</span>${badge(h.detection_connected?'Receiving frames':h.detection_service?.status||'Not started',h.detection_connected?'':'neutral')}</div><div class="status-row"><span>Cloud connection</span>${badge(h.cloud?.connected?'Connected':'Not connected',h.cloud?.connected?'':'neutral')}</div><div class="status-row"><span>Video persistence</span>${badge('Disabled','neutral')}</div><div class="status-row"><span>Version</span><strong>${esc(h.version||'0.1.0')}</strong></div></div></section></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Camera telemetry</h2><small>No invented inference metrics</small></div><div class="table-wrap"><table><thead><tr><th>Camera</th><th>Status</th><th>Detection fps</th><th>Inference</th><th>Decode</th><th>Last seen</th></tr></thead><tbody>${cameras().map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${badge(c.simulated?'Simulation':occupancy(c)?.available?'Online':'Offline',c.simulated?'amber':'neutral')}</td><td>${c.simulated?'—':c.metrics?.fps??'—'}</td><td>${c.simulated?'—':c.metrics?.inference_ms!=null?c.metrics.inference_ms+' ms':'—'}</td><td>${c.simulated?'—':esc(c.metrics?.decode||'—')}</td><td>${c.simulated?'Test input':timeAgo(c.metrics?.received_at)}</td></tr>`).join('')}</tbody></table></div></section>`;}
const eventNames={state:'Entity state changed',relay_command:'Relay command sent',override_released:'Manual override released',physical_override:'Wall button override',automation_saved:'Automation saved',camera_saved:'Camera configured',device_saved:'Wall switch configured',trace:'Automation run',mapping_saved:'Occupancy mapping updated',notification:'Automation notification',config_exported:'Configuration exported',backup_created:'Backup created',cloud_configured:'Cloud connection configured',device_online:'Device connected',settings_saved:'Site settings updated'};
function eventRow(e){const entity=entities().find(x=>x.id===e.entity);const title=eventNames[e.kind]||e.kind.replaceAll('_',' ');return `<div class="activity"><div class="activity-icon">${icon(e.kind==='state'?'pulse':e.kind.includes('override')?'person':e.kind.includes('automation')||e.kind==='trace'?'workflow':e.kind.includes('relay')?'bulb':'settings')}</div><p>${esc(title)}<small>${esc(entity?.name||e.entity)}${e.kind==='state'?` · ${esc(e.body.from)} → ${esc(e.body.to)}`:e.kind==='trace'?` · ${esc(e.body.result)}`:''}</small></p><time>${timeAgo(e.time)}</time></div>`;}
function renderHistory(){return pageHead()+`<div class="filter-row"><select id="history-entity" class="timeline-filter" aria-label="Filter activity by entity"><option value="">All entities and configuration events</option>${entities().map(e=>`<option value="${esc(e.id)}">${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Event</th><th>Entity / resource</th><th>Actor</th><th>Details</th></tr></thead><tbody id="history-body">${historyRows(state.events||[])}</tbody></table></div></section>`;}
function historyRows(events){return events.map(e=>`<tr><td>${date(e.time)}</td><td><strong>${esc(eventNames[e.kind]||e.kind.replaceAll('_',' '))}</strong></td><td><code>${esc(e.entity)}</code></td><td>${esc(e.actor)}</td><td><details><summary>View details</summary><pre class="trace">${esc(JSON.stringify(e.body,null,2))}</pre></details></td></tr>`).join('')||'<tr><td colspan="5">No activity recorded.</td></tr>';}
async function historyQuery(entity){return isRemote()?(state.events||[]).filter(e=>!entity||e.entity===entity):api('/api/history'+(entity?'?entity='+encodeURIComponent(entity):''));}
function renderZones(){if(!zoneCamera||!cameras().find(c=>c.id===zoneCamera)){zoneCamera=cameras()[0]?.id;zoneLocal=null;}const c=cameras().find(c=>c.id===zoneCamera);if(!c)return pageHead()+emptyInstall();if(!zoneLocal)zoneLocal=structuredClone(c);const z=zoneLocal;return pageHead(localAdmin()?'<button class="primary" id="save-zones">'+icon('save')+'Save boundaries</button>':'')+`<div class="filter-row"><select id="zone-camera" aria-label="Camera">${cameras().map(c=>`<option value="${esc(c.id)}" ${c.id===zoneCamera?'selected':''}>${esc(c.name)}</option>`).join('')}</select><small>Click to add vertices · Minimum 3 points · Stored as relative coordinates</small></div><div class="zone-layout"><section><div class="zone-canvas" id="zone-canvas">${c.simulated?scene(c):`<img src="/api/cameras/${encodeURIComponent(c.id)}/snapshot" alt="${esc(c.name)} snapshot"><div class="help" style="position:absolute;bottom:15px;left:15px">A live snapshot is needed to align the boundaries accurately.</div>`}<svg class="overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">${[...(z.zones||[]).map(p=>({...p,type:'zones'})),...(z.masks||[]).map(p=>({...p,type:'masks'}))].map(p=>`<polygon points="${p.points.map(([x,y])=>`${x*1000},${y*1000}`).join(' ')}" fill="${p.type==='masks'?'#df9b7433':'#b8f36c22'}" stroke="${p.type==='masks'?'#df9b74':'#b8f36c'}" stroke-width="3"/><text x="${p.points[0][0]*1000+8}" y="${p.points[0][1]*1000+22}" font-size="20" fill="#edf5df">${esc(p.name)}</text>`).join('')}<polyline points="${zoneDraft.map(([x,y])=>`${x*1000},${y*1000}`).join(' ')}" fill="#b8f36c22" stroke="#ecf8c8" stroke-width="3"/>${zoneDraft.map(([x,y])=>`<circle cx="${x*1000}" cy="${y*1000}" r="6" fill="#ecf8c8"/>`).join('')}</svg></div><div class="canvas-toolbar"><button id="finish-polygon" ${zoneDraft.length<3||!localAdmin()?'disabled':''}>${icon('check')}Finish ${zoneType==='zones'?'zone':'mask'} (${zoneDraft.length} points)</button><button id="undo-polygon" ${!zoneDraft.length?'disabled':''}>Undo point</button><button id="clear-polygon">Clear drawing</button></div><p class="help" style="margin-top:13px">Person occupancy uses the bottom centre of each detection box. Masks exclude motion and person detections. Zones and masks are not written to the camera.</p></section><aside class="panel"><div class="panel-head"><h2>Boundaries</h2>${icon('zones')}</div><div class="panel-body"><label>Draw a<select id="zone-type"><option value="zones" ${zoneType==='zones'?'selected':''}>Detection zone</option><option value="masks" ${zoneType==='masks'?'selected':''}>Exclusion mask</option></select></label><div style="margin-top:18px">${['zones','masks'].map(type=>`<div class="eyebrow" style="margin-top:20px">${type==='zones'?'DETECTION ZONES':'EXCLUSION MASKS'}</div>${z[type].map(p=>`<div class="zone-chip"><span>${esc(p.name)} <small>· ${p.points.length} points</small></span>${localAdmin()?`<button data-remove-zone="${esc(p.id)}" data-type="${type}" aria-label="Remove ${esc(p.name)}">${icon('trash')}</button>`:''}</div>`).join('')||'<p class="help">None configured</p>'}`).join('')}</div></div></aside></div>`;}
function renderSettings(){if(!isAdmin())return pageHead()+`<div class="empty">${icon('shield')}<h2>Administrator access required</h2><p>Your operator account can view status and control relays. Ask your administrator to change site settings.</p></div>`;if(isRemote())return pageHead()+`<div class="notice">Device credentials, backups and local network settings are managed on the local controller. The cloud stores the synchronized site configuration and state. Use Automations to send YAML updates remotely.</div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Remote command history</h2></div><div class="panel-body">${(window.cloudCommands||[]).reverse().map(c=>`<div class="status-row"><span>${esc(c.kind)} · ${timeAgo(c.created)}<small style="display:block">${esc(c.error||c.id)}</small></span>${badge(c.status,c.status==='failed'?'red':c.status==='pending'?'amber':'neutral')}</div>`).join('')||'<p class="help">No remote commands yet.</p>'}</div></section>`;return pageHead()+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Installation</h2>${icon('building')}</div><div class="panel-body"><form class="form-stack" id="site-settings"><label>Site name<input name="name" required value="${esc(state.settings.name)}"></label><div class="field-grid"><label>Timezone<input name="timezone" required value="${esc(state.settings.timezone)}"></label><label>History retention (days)<input name="history_days" type="number" min="1" max="365" value="${state.settings.history_days}"></label></div><button class="primary" type="submit">Save site settings</button></form></div></section><section class="panel"><div class="panel-head"><h2>Cloud connection</h2>${icon('cloud')}</div><div class="panel-body"><p class="form-note">Enroll a site in your cloud console, then enter its URL and one-time enrollment token here. Connections are outbound; local automation continues without internet. Video and device credentials stay local.</p><form id="cloud-form" class="form-stack" style="margin-top:18px"><label>Cloud console URL<input name="url" type="url" required placeholder="https://console.example.com"></label><label>Site enrollment token<input name="token" type="password" required autocomplete="off" placeholder="Paste the site's enrollment token"></label><div class="actions"><button class="primary" type="submit">Connect to cloud</button><button id="cloud-disconnect" type="button">Disconnect</button></div><p class="help">${esc(state.health.cloud?.message||'Not connected')}</p></form></div></section><section class="panel"><div class="panel-head"><h2>Configuration & recovery</h2>${icon('download')}</div><div class="panel-body"><p class="form-note">Export a portable site template without credentials. Database backups include encrypted credentials and account records; keep the encryption key alongside them in secure storage.</p><div class="form-stack" style="margin-top:18px"><button id="export-config">${icon('download')}Export site configuration</button><button id="import-config">${icon('upload')}Import into an empty installation</button><button id="download-backup">${icon('download')}Download database backup</button><input type="file" id="import-file" accept="application/json,.json" hidden><p class="help">Daily database backups retain the most recent seven files. See README for recovery and key protection.</p></div></div></section><section class="panel"><div class="panel-head"><h2>People & permissions</h2>${icon('person')}</div><div class="panel-body"><p class="form-note">Administrators configure the system. Operators can view status and manually control relays.</p><div id="users-list" style="margin-top:15px"></div><button id="add-user" style="margin-top:15px">${icon('plus')}Add user</button></div></section></div>`;}
function renderSites(){return pageHead(isAdmin()?'<button class="primary" id="add-site">'+icon('plus')+'Enroll installation</button>':'')+`<div class="notice" style="margin-bottom:22px">${icon('shield')} The local controller owns detection and control. This console stores synchronized site configuration and state, and routes authenticated commands over the controller's outbound connection.</div><div class="device-grid">${sites.map(s=>`<section class="panel cloud-site"><div class="site-identity">${icon('building')}<div><h2>${esc(s.name)}</h2><p class="help" style="margin-top:4px">${esc(s.location||'Local installation')}</p></div></div><div class="section-line">${badge(s.online?'Connected':'Offline',s.online?'':'neutral')}<small>${s.last_seen?'Last sync '+timeAgo(s.last_seen):'Not connected yet'}</small></div><button data-open-site="${esc(s.id)}" class="${s.online?'primary':''}">Open installation${icon('arrow')}</button></section>`).join('')||'<div class="empty">'+icon('cloud')+'<h2>Your installations, together.</h2><p>Enroll your first site to generate a connection token. Paste it into the local controller’s Cloud connection settings.</p></div>'}</div>`;}
function bind(){ $$('[data-page]').forEach(b=>b.onclick=e=>{e.preventDefault();setPage(b.dataset.page);});$('#logout').onclick=()=>guarded(async()=>{await api('/api/auth/logout',{});me=null;if(ws){ws.onclose=null;ws.close();}renderAuth(false);});$('#site-select')?.addEventListener('change',e=>openSite(e.target.value));$('#area-filter')?.addEventListener('change',e=>{area=e.target.value;render();});$('#search')?.addEventListener('input',e=>{query=e.target.value;const position=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(position,position);});$$('[data-area]').forEach(b=>b.onclick=()=>{area=b.dataset.area;render();});$$('[data-camera]').forEach(b=>b.onclick=()=>cameraDetail(b.dataset.camera));$$('[data-relay]').forEach(b=>b.onclick=()=>guarded(async()=>{b.disabled=true;const id=b.dataset.relay;if(isRemote()){await api(`/api/cloud/sites/${cloudSite}/commands`,{kind:'relay',data:{entity_id:id,action:'toggle'}});toast('Command queued. Waiting for confirmation from the site.');}else{await api(`/api/relays/${encodeURIComponent(id)}/command`,{action:'toggle'});toast('Relay state confirmed. Manual override is active.');}await refresh();}));$$('[data-map]').forEach(b=>b.onclick=()=>mappingDialog(b.dataset.map));$$('[data-add-camera]').forEach(b=>b.onclick=()=>cameraDialog());$$('[data-camera-edit]').forEach(b=>b.onclick=()=>cameraDialog(b.dataset.cameraEdit));$$('[data-add-device]').forEach(b=>b.onclick=()=>deviceDialog());$$('[data-device-edit]').forEach(b=>b.onclick=()=>deviceDialog(b.dataset.deviceEdit));$('#load-demo')?.addEventListener('click',()=>confirmDialog('Load the simulation workspace?','This adds 12 simulated cameras, 36 simulated four-relay switches and sample occupancy mappings. It does not create automation rules or connect to hardware.',()=>guarded(async()=>{await api('/api/demo',{});await refresh();toast('Simulation loaded. Add rules in Automations when ready.');})));bindAutomations();bindZones();bindSettings();$('#history-entity')?.addEventListener('change',e=>guarded(async()=>{$('#history-body').innerHTML=historyRows(await historyQuery(e.target.value));}));$('#add-site')?.addEventListener('click',addSiteDialog);$$('[data-open-site]').forEach(b=>b.onclick=()=>guarded(()=>openSite(b.dataset.openSite)));}
function baseCameraDetail(id){const c=cameras().find(c=>c.id===id),e=occupancy(c);modal(c.name,`<div class="live-large">${c.simulated?scene(c):!isRemote()?`<img src="/api/cameras/${encodeURIComponent(id)}/live" alt="Live camera view">`:'<div class="empty">Live video stays at the local site.</div>'}<svg class="overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">${c.zones.map(z=>`<polygon class="occupancy-marker" points="${z.points.map(([x,y])=>`${x*1000},${y*1000}`).join(' ')}"/>`).join('')}</svg></div><div class="pill-row">${badge(c.simulated?'Simulated camera':e?.available?'Live':'Offline',c.simulated?'amber':'neutral')}${badge(e?.state===true?'Occupied':e?.state===false?'Clear':'Unknown',e?.state===true?'':'neutral')}${badge(c.area,'neutral')}</div><div class="detail-rows"><div><small>Occupancy entity</small><code>${esc(e?.id||'—')}</code></div><div><small>Clear delay</small>${c.off_delay}s · ${c.disappear_frames} absent frames</div></div>${c.simulated&&localAdmin()?`<div class="notice" style="margin-top:18px">Simulation inputs represent stable observations after debounce. Use these to test rules and manual override release.</div><div class="dialog-actions"><button id="simulate-clear">${icon('check')}Set view clear</button><button id="simulate-person" class="primary">${icon('person')}Simulate a person</button></div>`:''}`,d=>{const run=present=>guarded(async()=>{await api(`/api/simulation/${id}`,{detections:present?[{box:[.43,.2,.6,.8],score:.95}]:[]});d.close();await refresh();toast(present?'Simulated occupancy set to occupied':'Simulated view is clear. Eligible overrides released.');});$('#simulate-clear',d)?.addEventListener('click',()=>run(false));$('#simulate-person',d)?.addEventListener('click',()=>run(true));});}
function cameraDialog(id){const c=cameras().find(x=>x.id===id)||{name:'',area:'Production',fps:5,width:640,height:360,threshold:.5,confirm_frames:2,disappear_frames:10,off_delay:10};modal(id?'Configure camera':'Connect a camera',`<form id="camera-form"><div class="field-grid"><label>Camera name<input name="name" required value="${esc(c.name)}" placeholder="Sewing line A"></label><label>Area / floor<input name="area" required value="${esc(c.area)}"></label><label class="wide">RTSP detection stream URL<input name="rtsp_url" type="password" autocomplete="off" placeholder="${c.has_stream?'Configured — leave blank to keep':'rtsp://user:password@192.168.1.10:554/substream'}"></label><label class="wide checkbox-line"><input name="simulated" type="checkbox" ${c.simulated?'checked':''}>Simulated camera (no physical stream)</label><label>Detection fps<input name="fps" type="number" min="1" max="15" step="1" value="${c.fps}"></label><label>Confidence threshold<input name="threshold" type="number" min=".05" max="1" step=".05" value="${c.threshold}"></label><label>Decode width<input name="width" type="number" min="160" max="1920" step="2" value="${c.width}"></label><label>Decode height<input name="height" type="number" min="120" max="1080" step="2" value="${c.height}"></label><label>Confirm frames<input name="confirm_frames" type="number" min="1" max="100" value="${c.confirm_frames}"></label><label>Disappear frames<input name="disappear_frames" type="number" min="1" max="500" value="${c.disappear_frames}"></label><label>Off delay (seconds)<input name="off_delay" type="number" min="0" max="3600" value="${c.off_delay}"></label><label class="checkbox-line"><input name="enabled" type="checkbox" ${c.enabled!==false?'checked':''}>Camera enabled</label></div><p class="help" style="margin-top:15px">Use a low-resolution substream for detection. Stream URLs are encrypted on the local controller and excluded from cloud sync and exports. Model settings are configured on the detection worker.</p><div class="error" id="form-error"></div><div class="dialog-actions">${id?'<button type="button" class="danger" id="delete-camera">'+icon('trash')+'Remove</button>':''}<button class="primary" type="submit">Save camera</button></div></form>`,d=>{$('#camera-form',d).onsubmit=e=>{e.preventDefault();guarded(async()=>{const f=Object.fromEntries(new FormData(e.target));const payload={...(id?c:{}),...f,simulated:!!f.simulated,enabled:!!f.enabled};for(const k of ['fps','width','height','threshold','confirm_frames','disappear_frames','off_delay'])payload[k]=Number(payload[k]);if(!f.rtsp_url)delete payload.rtsp_url;await api('/api/cameras',payload);d.close();await refresh();toast('Camera configuration saved');});};$('#delete-camera',d)?.addEventListener('click',()=>confirmDialog('Remove camera?',`Remove ${c.name} and its occupancy entities. Referenced entities must be unmapped first.`,async()=>{await api(`/api/cameras/${id}`,undefined,'DELETE');await refresh();}));});}
function deviceDialog(id){const dvc=devices().find(d=>d.id===id)||{name:'',area:'Production',host:'',port:6053,relay_count:4};modal(id?'Configure wall switch':'Connect an ESPHome wall switch',`<form id="device-form"><div class="field-grid"><label>Device name<input name="name" required value="${esc(dvc.name)}" placeholder="Wall switch 01"></label><label>Area / floor<input name="area" required value="${esc(dvc.area)}"></label><label>Reserved IP / hostname<input name="host" value="${esc(dvc.host)}" placeholder="192.168.1.101"></label><label>Native API port<input name="port" type="number" value="${dvc.port}" min="1" max="65535"></label><label class="wide">ESPHome API encryption key<input name="api_key" type="password" autocomplete="off" placeholder="${dvc.has_key?'Configured — leave blank to keep':'Paste api.encryption.key from ESPHome'}"></label><label class="checkbox-line wide"><input name="simulated" type="checkbox" ${dvc.simulated?'checked':''} ${id?'disabled':''}>Simulated device (no hardware connection)</label><label>Simulated relay count<input name="relay_count" type="number" min="1" max="16" value="${dvc.relay_count}"></label></div><p class="help" style="margin-top:16px">Real relay names and keys are discovered from ESPHome. Your firmware uses ESP8266 with four relays. Factory-reset switches are excluded. Credentials remain encrypted locally.</p><div class="dialog-actions">${id?'<button type="button" class="danger" id="delete-device">'+icon('trash')+'Remove</button>':''}<button type="submit" class="primary">Save wall switch</button></div></form>`,d=>{$('#device-form',d).onsubmit=e=>{e.preventDefault();guarded(async()=>{const f=Object.fromEntries(new FormData(e.target));const payload={...(id?dvc:{}),...f,simulated:id?dvc.simulated:!!f.simulated,port:Number(f.port),relay_count:Number(f.relay_count)};if(!f.api_key)delete payload.api_key;await api('/api/devices',payload);d.close();await refresh();toast('Wall switch saved. Real devices connect automatically.');});};$('#delete-device',d)?.addEventListener('click',()=>confirmDialog('Remove wall switch?',`Remove ${dvc.name} and its relays. Automations referencing them must be updated first.`,async()=>{await api(`/api/devices/${id}`,undefined,'DELETE');await refresh();}));});}
function mappingDialog(id){const entity=entities().find(e=>e.id===id);modal('Map occupancy for '+entity.name,`<form id="mapping-form" class="form-stack"><p class="form-note">Select every camera or zone covering this load. A manual override releases only when every selected source and its entire parent camera view are available and clear. With no mapping, an override stays active.</p><div style="max-height:360px;overflow:auto">${entities().filter(e=>e.type==='occupancy_sensor').map(e=>`<label class="checkbox-line" style="padding:9px 0"><input type="checkbox" name="sources" value="${esc(e.id)}" ${entity.occupancy_sources?.includes(e.id)?'checked':''}><span>${esc(e.name)}<small style="display:block">${esc(e.id)}</small></span></label>`).join('')}</div><div class="dialog-actions"><button class="primary" type="submit">Save mapping</button></div></form>`,d=>{$('#mapping-form',d).onsubmit=e=>{e.preventDefault();guarded(async()=>{const sources=new FormData(e.target).getAll('sources');await api(`/api/relays/${id}/mapping`,{occupancy_sources:sources},'PUT');d.close();await refresh();toast('Occupancy mapping saved');});};});}
function bindAutomations(){if(page!=='automations')return;$('#yaml-editor')?.addEventListener('input',()=>{editorDirty=true;$('#validation').textContent='Unsaved changes';});$('#yaml-editor')?.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target,a=t.selectionStart,b=t.selectionEnd;t.setRangeText('  ',a,b,'end');editorDirty=true;}});$('#new-auto')?.addEventListener('click',()=>{if(editorDirty){confirmDialog('Start a new automation?','Unsaved changes will be discarded.',()=>{editorDirty=false;currentAuto=null;render();});}else{currentAuto=null;render();}});$$('[data-auto]').forEach(b=>b.onclick=()=>{const run=()=>{editorDirty=false;currentAuto=b.dataset.auto;render();};if(editorDirty)confirmDialog('Switch automations?','Unsaved changes will be discarded.',run);else run();});$('#visual-mode')?.addEventListener('click',visualBuilder);$('#validate-auto')?.addEventListener('click',()=>guarded(async()=>{await api('/api/automations/validate',{yaml:$('#yaml-editor').value});$('#validation').textContent='✓ Valid YAML and entity references';toast('Automation validated');}));const save=async enabled=>{const record=state.automations.find(a=>a.id===currentAuto);const data={id:currentAuto,yaml:$('#yaml-editor').value,enabled:enabled??record?.enabled??true};if(isRemote()){const result=await api(`/api/cloud/sites/${cloudSite}/commands`,{kind:'automation',data});toast('YAML queued for local validation and application. Check command history for confirmation.');}else{const result=await api('/api/automations',data);currentAuto=result.id;toast('Automation saved and applied');}editorDirty=false;await refresh();};$('#save-auto')?.addEventListener('click',()=>guarded(()=>save()));$('#toggle-auto')?.addEventListener('click',()=>guarded(()=>save(!state.automations.find(a=>a.id===currentAuto).enabled)));$$('[data-run-auto]').forEach(b=>b.onclick=()=>guarded(async()=>{await api(`/api/automations/${b.dataset.runAuto}/run`,{});toast('Automation triggered. Check its run trace.');}));$('#delete-auto')?.addEventListener('click',()=>confirmDialog('Delete automation?','This removes the rule and cancels its active runs.',async()=>{await api(`/api/automations/${currentAuto}`,undefined,'DELETE');editorDirty=false;currentAuto=null;await refresh();}));}
function bindZones(){if(page!=='zones')return;$('#zone-camera')?.addEventListener('change',e=>{zoneCamera=e.target.value;zoneLocal=null;zoneDraft=[];render();});$('#zone-type')?.addEventListener('change',e=>{zoneType=e.target.value;});$('#zone-canvas')?.addEventListener('click',e=>{if(!localAdmin())return;const rect=e.currentTarget.getBoundingClientRect();zoneDraft.push([Number(((e.clientX-rect.left)/rect.width).toFixed(4)),Number(((e.clientY-rect.top)/rect.height).toFixed(4))]);render();});$('#undo-polygon')?.addEventListener('click',()=>{zoneDraft.pop();render();});$('#clear-polygon')?.addEventListener('click',()=>{zoneDraft=[];render();});$('#finish-polygon')?.addEventListener('click',()=>modal('Name this '+(zoneType==='zones'?'zone':'mask'),'<form id="boundary-name"><label>Name<input name="name" required maxlength="80" placeholder="Work area"></label><div class="dialog-actions"><button type="submit" class="primary">Add boundary</button></div></form>',d=>{$('#boundary-name',d).onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name');zoneLocal[zoneType].push({id:'z_'+crypto.getRandomValues(new Uint32Array(1))[0].toString(16),name,points:zoneDraft});zoneDraft=[];d.close();render();};}));$$('[data-remove-zone]').forEach(b=>b.onclick=()=>{zoneLocal[b.dataset.type]=zoneLocal[b.dataset.type].filter(p=>p.id!==b.dataset.removeZone);render();});$('#save-zones')?.addEventListener('click',()=>guarded(async()=>{await api('/api/cameras',zoneLocal);zoneLocal=null;state=await api('/api/state');render();toast('Zones and masks saved');}));}
async function download(url,filename,method='GET'){const response=await fetch(url,{method,headers:{'X-LumiNext':'1'}});if(!response.ok){const data=await response.json();throw Error(data.detail);}const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function bindSettings(){if(page!=='settings')return;$('#site-settings')?.addEventListener('submit',e=>{e.preventDefault();guarded(async()=>{await api('/api/settings',Object.fromEntries(new FormData(e.target)));await refresh();toast('Site settings saved');});});$('#cloud-form')?.addEventListener('submit',e=>{e.preventDefault();guarded(async()=>{await api('/api/cloud/connect',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Connection configured. The controller will synchronize shortly.');});});$('#cloud-disconnect')?.addEventListener('click',()=>guarded(async()=>{await api('/api/cloud/connect',undefined,'DELETE');toast('Cloud connection removed');await refresh();}));$('#export-config')?.addEventListener('click',()=>guarded(()=>download('/api/config/export','luminext-site.json')));$('#download-backup')?.addEventListener('click',()=>guarded(()=>download('/api/backup','luminext-backup.db','POST')));$('#import-config')?.addEventListener('click',()=>$('#import-file').click());$('#import-file')?.addEventListener('change',e=>guarded(async()=>{const file=e.target.files[0];if(!file)return;if(file.size>4_000_000)throw Error('File exceeds 4 MB');const data=JSON.parse(await file.text());await api('/api/config/import',data);await refresh();toast('Site imported. Enter device keys and RTSP URLs locally.');}));$('#add-user')?.addEventListener('click',()=>modal('Add a user','<form id="user-form" class="form-stack"><label>Username<input name="username" required minlength="3" maxlength="64"></label><label>Password<input name="password" type="password" required minlength="12" autocomplete="new-password"></label><label>Role<select name="role"><option value="operator">Operator — view and manual control</option><option value="admin">Administrator — full configuration</option></select></label><div class="dialog-actions"><button class="primary" type="submit">Create user</button></div></form>',d=>{$('#user-form',d).onsubmit=e=>{e.preventDefault();guarded(async()=>{await api('/api/users',Object.fromEntries(new FormData(e.target)));d.close();await loadUsers();toast('Account created');});};}));if($('#users-list'))loadUsers();}
async function loadUsers(){await guarded(async()=>{const users=await api('/api/users');if(!$('#users-list'))return;$('#users-list').innerHTML=users.map(u=>`<div class="status-row"><span>${esc(u.username)} ${badge(u.role,'neutral')}</span>${u.id!==me.id?`<button class="compact danger" data-delete-user="${esc(u.id)}" aria-label="Remove ${esc(u.username)}">${icon('trash')}</button>`:'<small>Your account</small>'}</div>`).join('');$$('[data-delete-user]').forEach(b=>b.onclick=()=>confirmDialog('Remove user?','All sessions for this account will be revoked.',async()=>{await api(`/api/users/${b.dataset.deleteUser}`,undefined,'DELETE');await loadUsers();}));});}
async function openSite(id){cloudSite=id;const result=await api(`/api/cloud/sites/${id}/state`);state=result.snapshot;cloudOnline=result.online;window.cloudCommands=result.commands;page='overview';editorDirty=false;currentAuto=null;render();}
function addSiteDialog(){modal('Enroll a local installation','<form id="site-form" class="form-stack"><label>Installation name<input name="name" required placeholder="Factory — Dhaka"></label><label>Location<input name="location" placeholder="Building or city"></label><p class="form-note">You’ll receive a site token once. Store it securely and paste it into the local controller’s Cloud connection settings.</p><div class="dialog-actions"><button class="primary" type="submit">Generate site token</button></div></form>',d=>{$('#site-form',d).onsubmit=e=>{e.preventDefault();guarded(async()=>{const result=await api('/api/cloud/sites',Object.fromEntries(new FormData(e.target)));sites=await api('/api/cloud/sites');render();modal('Site enrolled','<p class="form-note">Copy this token now. It will not be shown again. Enter it with this console’s HTTPS URL in the local controller’s settings.</p><div class="token" id="enrollment-token"></div><div class="dialog-actions"><button data-close-token class="primary">I have saved the token</button></div>',dialog=>{$('#enrollment-token',dialog).textContent=result.token;$('[data-close-token]',dialog).onclick=()=>dialog.close();});});};});}
function cameraDetail(id){
  if(activePeer){activePeer.close();activePeer=null;}
  baseCameraDetail(id);
  const camera=cameras().find(c=>c.id===id);
  if(!camera.simulated){const diagnostic=document.createElement('p');diagnostic.className='form-note';diagnostic.style.marginTop='15px';diagnostic.textContent=camera.connection_message||'Check detection worker status under System health.';$('.dialog-body').append(diagnostic);}
  if(camera.simulated||isRemote())return;
  const button=document.createElement('button');
  button.className='compact';button.style.marginTop='15px';button.textContent='Play low-latency WebRTC';
  $('.dialog-body').append(button);
  button.onclick=()=>guarded(async()=>{
    button.disabled=true;
    const pc=new RTCPeerConnection({iceServers:[]});activePeer=pc;
    const video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;video.style.cssText='width:100%;height:100%;object-fit:contain';
    pc.ontrack=event=>{video.srcObject=event.streams[0]||new MediaStream([event.track]);};
    pc.addTransceiver('video',{direction:'recvonly'});
    try{
      await pc.setLocalDescription(await pc.createOffer());
      if(pc.iceGatheringState!=='complete')await new Promise(resolve=>{const timer=setTimeout(resolve,3000);pc.onicegatheringstatechange=()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timer);resolve();}};});
      const answer=await api(`/api/cameras/${encodeURIComponent(id)}/webrtc`,{sdp:pc.localDescription.sdp});
      await pc.setRemoteDescription({type:'answer',sdp:answer.sdp});
      const visual=$('.live-large');const image=$('img',visual);if(image)image.remove();visual.prepend(video);
      button.textContent='WebRTC · direct encrypted media';
      pc.onconnectionstatechange=()=>{if(pc.connectionState==='failed'){button.textContent='WebRTC failed — reopen for JPEG fallback';pc.close();}};
    }catch(error){pc.close();activePeer=null;button.disabled=false;throw error;}
  });
}
$('#dialog').addEventListener('close',()=>{if(activePeer){activePeer.close();activePeer=null;}});
document.addEventListener('keydown',event=>{if(event.target.dataset?.camera&&['Enter',' '].includes(event.key)){event.preventDefault();cameraDetail(event.target.dataset.camera);}});
window.addEventListener('beforeunload',e=>{if(editorDirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{const value=location.hash.slice(1);if(pages[value]&&value!==page)setPage(value);});
setInterval(()=>{if(me&&state&&page==='health'&&!$('#dialog').open)refresh();},5000);
setInterval(()=>{if(me&&mode==='cloud'&&!$('#dialog').open)refresh();},5000);
boot();
